fn main() {
    let manifest_dir = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap());
    let linker_script = manifest_dir.join("linker.ld");

    // Скрипт компоновки: старшая половина, отдельные PT_LOAD для W^X.
