impl StackSizeRequest {
    const fn new(id: [u64; 4], stack_size: u64) -> Self {
        Self {
            id,
            revision: 0,
            response: ptr::null_mut(),
            stack_size,
        }
    }
}

#[repr(C)]
pub struct HhdmResponse {
    pub revision: u64,
    pub offset: u64,
}

#[repr(C)]
pub struct FramebufferResponse {
    pub revision: u64,
    pub framebuffer_count: u64,
    pub framebuffers: *mut *mut Framebuffer,
