unsafe impl<R: Sync> Sync for Request<R> {}""",
"""// SAFETY: структура состоит из магии, номера ревизии и указателя на ответ,
// который пишет загрузчик до передачи управления ядру. После старта ядра
// запрос только читается, поэтому разделять его между потоками безопасно.
unsafe impl<R> Sync for Request<R> {}""")
s=s.replace("""    // SAFETY: загрузчик гарантирует массив из entry_count указателей на
    // записи, живущие всё время работы ядра.
    unsafe { core::slice::from_raw_parts(response.entries, response.entry_count as usize) }""",
"""    // SAFETY: загрузчик гарантирует массив из entry_count ненулевых указателей
    // на записи, живущие всё время работы ядра. Представление `&T` и `*mut T`
    // совпадает (гарантия Rust для ссылок на Sized-типы), поэтому массив
    // указателей можно читать как срез ссылок.
    unsafe {
        core::slice::from_raw_parts(
            response.entries as *const &'static MemmapEntry,
            response.entry_count as usize,
        )
    }""")
open(p,'w').write(s)

p='kernel/src/console/fb.rs'
s=open(p).read()
s=s.replace("""pub struct FramebufferConsole {""",
"""/// SAFETY: консоль — это указатель на отображённую память framebuffer и
/// счётчики. Владелец (мьютекс консоли) сериализует доступ, поэтому консоль
/// можно передавать между потоками.
unsafe impl Send for FramebufferConsole {}

pub struct FramebufferConsole {""")
open(p,'w').write(s)

p='kernel/src/console/mod.rs'
s=open(p).read()
s=s.replace('    println!(\n        "console: serial=', '    crate::println!(\n        "console: serial=')
s=s.replace('        println!(\n            "console: framebuffer', '        crate::println!(\n            "console: framebuffer')
s=s.replace('        println!("console: framebuffer недоступен', '        crate::println!("console: framebuffer недоступен')
open(p,'w').write(s)
print("patched")
